const cfg = $('Config').first().json;
const NAME = { cs: /czech/i, da: /danish/i, de: /german/i, el: /greek/i, es: /spanish/i, fr: /french/i, hr: /croatian/i, id: /indonesian/i, it: /italian/i, ko: /korean/i, ms: /malay/i, nl: /dutch/i, no: /norwegian/i, pl: /polish/i, pt: /portuguese/i, ro: /romanian/i, sk: /slovak/i, sv: /swedish/i, th: /thai/i, tr: /turkish/i, uk: /ukr/i, vi: /vietnamese/i };
const files = (($input.first().json || {}).files) || [];
const out = [];
