const cfg = $('Config').first().json;
const LN = { cs: 'Czech', da: 'Danish', de: 'German', el: 'Greek', es: 'Spanish', fr: 'French', hr: 'Croatian', id: 'Indonesian', it: 'Italian', ko: 'Korean', ms: 'Malay', nl: 'Dutch', no: 'Norwegian (Bokmål)', pl: 'Polish', pt: 'Brazilian Portuguese (pt-BR)', ro: 'Romanian', sk: 'Slovak', sv: 'Swedish', th: 'Thai', tr: 'Turkish', uk: 'Ukrainian', vi: 'Vietnamese' };
const ISO_BY_ID = { 765: 'cs', 767: 'da', 666: 'de', 761: 'el', 640: 'en', 1056: 'es', 673: 'fr', 793: 'hr', 757: 'id', 734: 'it', 733: 'ko', 749: 'ms', 737: 'nl', 760: 'no', 759: 'no', 748: 'pl', 708: 'pt', 770: 'ro', 799: 'sk', 754: 'sv', 753: 'th', 744: 'tr', 769: 'uk', 774: 'vi' };
function txt(v) { if (v === null || v === undefined || typeof v === 'object') { return ''; } return String(v); }
function kn(k) { const n = k.key_name || {}; return typeof n === 'string' ? n : (n.web || n.other || ''); }
function rows(items) { const out = []; for (const it of items) { const b = it.json.body || {}; if (!Array.isArray(b.keys)) { continue; } for (const k of b.keys) { if (k.is_archived) { continue; } const tr = {}; let en = ''; for (const t of (k.translations || [])) { const s = txt(t.translation); if (t.language_iso === 'en') { en = s; } else if (s.trim()) { tr[t.language_iso] = s; } } if (!en.trim()) { continue; } out.push({ id: k.key_id, name: kn(k), en: en, t: tr, d: String(k.description || '') }); } } return out; }
const targets = rows($('Fetch targets').all());
if (!targets.length) { throw new Error('No keys tagged ' + cfg.tag); }
const tid = {}; for (const t of targets) { tid[t.id] = 1; }
const corpus = rows($('Fetch corpus').all()).filter(function (c) { return !tid[c.id]; });
function norm(s) { return String(s).replace(/<[^>]+>/g, ' ').replace(/\[%[^\]]*\]/g, ' X ').replace(/[’‘]/g, "'").replace(/\s+/g, ' ').trim().toLowerCase(); }
function toks(s) { return new Set((norm(s).match(/[\p{L}\p{N}']{2,}/gu) || [])); }
for (const c of corpus) { c.n = norm(c.en); c.w = toks(c.en); }
for (const t of targets) {
  t.n = norm(t.en); const W = toks(t.en); const m = [];
  for (const c of corpus) {
    if (!c.w.size) { continue; }
    if (c.n === t.n) { m.push({ c: c, sc: 1 }); continue; }
    if (W.size < 2) { continue; }
    const r = c.w.size / W.size; if (r < 0.5 || r > 2) { continue; }
    let i = 0; W.forEach(function (x) { if (c.w.has(x)) { i++; } });
    const sc = 2 * i / (W.size + c.w.size); if (sc >= 0.6) { m.push({ c: c, sc: sc }); }
  }
  m.sort(function (a, b) { return b.sc - a.sc; });
  t.tm = m.slice(0, 4);
  const parts = t.name.split('::');
  const parent = parts.slice(0, parts.length - 1).join('::') + '::';
  const pre = parts.slice(0, Math.min(3, parts.length - 1)).join('::') + '::';
  const near = corpus.filter(function (c) { return c.name.indexOf(parent) === 0 && c.en.length < 300; });
  const wide = corpus.filter(function (c) { return c.name.indexOf(parent) !== 0 && c.name.indexOf(pre) === 0 && c.en.length < 220; });
  t.sib = near.slice(0, 6).concat(wide.slice(0, 6));
}
const RULES = {}, JUDGE = {};
for (const it of $('Style rules').all()) { const r = it.json || {}; if (!r.iso || r.iso === '*') { continue; } let l = []; try { l = JSON.parse(r.rules_json || '[]'); } catch (e) { } RULES[r.iso] = l.filter(function (x) { return !x.project || x.project !== 'personality'; }).map(function (x) { return (x.desc || x.id) + (x.suggest ? ' (use: ' + x.suggest + ')' : ''); }); JUDGE[r.iso] = r.judgement || ''; }
const FB = {};
for (const it of $('Feedback').all()) { const r = it.json || {}; if (!r.iso || !r.decision) { continue; } (FB[r.iso] = FB[r.iso] || []).push({ d: r.decision, rule: String(r.rule || '').slice(0, 80), en: String(r.en || '').slice(0, 120), t: String(r.translation || '').slice(0, 120), why: String(r.reason || r.issue || '').slice(0, 160) }); }
const GUIDE = {};
const gp = $('Guide plan').all(); const ge = $('Export guides').all();
for (let i = 0; i < gp.length; i++) { const iso = gp[i].json.iso; const g = ge[i] ? ge[i].json : {}; const s = typeof g.data === 'string' ? g.data : ''; if (s && iso !== '__none__') { GUIDE[iso] = s.replace(/\r/g, '').replace(/\n{3,}/g, '\n\n').slice(0, 24000); } }
let terms = [];
for (const it of $('Glossary').all()) { const b = it.json.body !== undefined ? it.json.body : it.json; terms = terms.concat((b && (b.data || b.glossary_terms || b.terms)) || []); }
function yes(v) { return v === true || v === 1 || String(v).toLowerCase() === 'yes' || String(v).toLowerCase() === 'true'; }
function tagList(t) { const raw = t.tags || []; const arr = Array.isArray(raw) ? raw : String(raw).split(','); return arr.map(function (x) { return String(typeof x === 'object' && x ? (x.name || x.tag || '') : x).trim().toLowerCase(); }).filter(function (x) { return x; }); }
const inScope = terms.filter(function (t) { const tg = tagList(t); return !tg.length || tg.indexOf('shared') !== -1 || tg.indexOf('realchecker') !== -1; });
const WL = /[\p{L}\p{N}]/u;
function hasTerm(blob, term, cs) { const B = cs ? blob : blob.toLowerCase(); const T = cs ? term : term.toLowerCase(); let i = B.indexOf(T); while (i !== -1) { const a = i > 0 ? B.charAt(i - 1) : ' '; const z = B.charAt(i + T.length) || ' '; if (!WL.test(a) && !WL.test(z)) { return true; } i = B.indexOf(T, i + 1); } return false; }
function glossFor(iso, ens) {
  const out = []; const blob = ens.join(' | ');
  for (const t of inScope) {
    const src = String(t.term || '').trim(); if (!src) { continue; }
    if (!hasTerm(blob, src, yes(t.caseSensitive))) { continue; }
    let tgt = '', note = '';
    for (const tr of (t.translations || [])) { const i2 = ISO_BY_ID[tr.langId || tr.lang_id] || (String(tr.langIso || tr.lang_iso || '') === 'pt_BR' ? 'pt' : String(tr.langIso || tr.lang_iso || '')); if (i2 === iso) { tgt = String(tr.translation || '').trim(); note = String(tr.description || '').trim(); } }
    const translatable = t.translatable === undefined ? true : yes(t.translatable);
    if (translatable && !tgt && !yes(t.forbidden)) { continue; }
    out.push({ term: src, target: translatable ? tgt : '(do not translate: keep as is)', forbidden: yes(t.forbidden) || undefined, note: (note || String(t.description || '')).slice(0, 160) || undefined });
  }
