}
const NL = String.fromCharCode(10);
const jobs = [];
for (const iso of cfg.langs) {
  const items = targets.map(function (t) { const tm = []; for (const x of t.tm) { if (x.c.t[iso]) { tm.push({ match: x.sc === 1 ? '100% (exact)' : 'fuzzy ' + Math.round(x.sc * 100) + '%', en: x.c.en, translation: x.c.t[iso] }); } } return { id: String(t.id), key: t.name, en: t.en, previous_translation: t.t[iso] || '', context: t.d.slice(0, 600) || undefined, tm: tm.length ? tm.slice(0, 3) : undefined }; });
  const sibs = []; const seen = {};
  for (const t of targets) { for (const s of t.sib) { if (seen[s.id] || !s.t[iso]) { continue; } seen[s.id] = 1; sibs.push({ key: s.name, en: s.en, t: s.t[iso] }); } }
  const fb = (FB[iso] || []).slice(-15);
  const SYS = [
    'You are a senior native ' + LN[iso] + ' localizer for RealChecker, a web app for reverse phone, email, VIN and image lookup. These strings all come from the VIN lookup page, where a car buyer enters a VIN to get a vehicle history report: three short checklist lines in the hero block at the top (hero::check_1, check_2, check_3, each shown next to a check mark), the body copy of a why-use-this feature card, and an FAQ answer. The product team updated the English source. Each item gives the CURRENT English and the PREVIOUS ' + LN[iso] + ' translation, which was made for an older English text. The three hero checklist lines now say something quite different (old English: Decode any VIN in seconds - year, make, model and trim / Uncover title brands, mileage and accident records from public sources / Search with complete confidence - your privacy is always protected). The feature card and the FAQ answer keep their meaning; the English only dropped a dash.',
    'TASK: return the ' + LN[iso] + ' translation that matches the CURRENT English exactly in meaning. If the previous translation is empty, translate from scratch. Otherwise rework it: keep its wording and terminology where it still matches the current English; change, add or remove whatever the English changed. Do not keep content the current English no longer says, and do not omit anything it now says. If the previous translation is about something else, translate from scratch. If it already matches the current English and follows the style guide and glossary, return it unchanged.',
    'Write natural, idiomatic, concise product copy a native speaker expects in a polished web app, not a literal rendering.',
    'PRIORITIES, in order: (1) the ' + LN[iso] + ' STYLE GUIDE below (register/formality, tone, typography, number/unit/punctuation conventions); (2) the GLOSSARY (use the approved target terms; never use forbidden terms; keep brand names like RealChecker unchanged); (3) TRANSLATION MEMORY matches attached to items (approved translations of the same or similar English); (4) same_page_strings: existing translations of nearby strings; keep terminology, tone and naming consistent with them (how VIN, report, vehicle history, make, model, trim, mileage, accident and title records are rendered).',
    'BINDING NOTES FOR THIS BATCH: (a) HERO CHECKLIST (hero::check_1, check_2, check_3): three short benefit lines shown as a list next to check marks. Keep them short and give all three the same grammatical form (the form your previous translations of these lines used, if it fits the style guide), no final full stop, no dash. (b) check_1 Confirm the vehicle make, model and trim in seconds = check that the car really is the make, model and trim (trim level / equipment version) it is said to be; render trim the way same_page_strings render it; there is no year and no decoding any more. (c) check_2 Spot potential red flags in accident, mileage and title records = notice possible warning signs (problems) in the car accident history, mileage records and title records. Title records = the vehicle legal title / registration history (e.g. salvage or rebuilt brands), never a heading or a document name; render it as same_page_strings do. Keep potential. There is no mention of public sources any more. (d) check_3 Search privately and buy with greater confidence = your search stays private, and you buy the car feeling more confident; two ideas, privately and buy with greater confidence; no complete confidence and no always protected any more. (e) why::feature_4_description and faqs::question_6::answer: the meaning did not change, only the punctuation. Keep the previous translation word for word and change only what the punctuation change requires: in feature_4_description, remove the dash and join the two parts with the plain conjunction for and (as the English does), adjusting the comma only if your language needs it; in question_6 answer, the English now reads No. Your search is private. We only access ... : remove the dash, end the sentence after private and start a new sentence with the equivalent of We only access, capitalised. Also fix any clear style-guide breach in these two strings (register, quotation marks), but nothing else. (f) Never use the & sign; write the conjunction in full. Never use a dash where the English has none.',
    'Read each item context (key description) for placement and audience.',
    'MECHANICS (strict): keep every placeholder exactly as in the source; keep tags with the translated text inside; keep ICU syntax if present. Do not add leading/trailing spaces. Keep brand names as the glossary says.',
    'Return ONLY JSON: {"t":{"<id>":"<translation>", ...}} keyed by the numeric item id, with an entry for EVERY id.',
    '',
    '=== ' + LN[iso] + ' STYLE GUIDE (source of truth) ===',
    GUIDE[iso] ? GUIDE[iso] : '(full guide unavailable; use the rules below)',
    '',
    '=== Style rules distilled by the i18n team ===',
    (RULES[iso] || []).slice(0, 40).join(NL) || '(none)',
    JUDGE[iso] ? ('Judgement notes: ' + JUDGE[iso]) : '',
    fb.length ? ('Reviewer precedent (i18n lead decisions on earlier audits, follow them): ' + JSON.stringify(fb)) : ''
  ].join(NL);
  const user = { language: LN[iso], glossary: glossFor(iso, targets.map(function (t) { return t.en; })), same_page_strings: sibs.slice(0, 80), items: items };
  jobs.push({ json: { iso: iso, guide: !!GUIDE[iso], body: JSON.stringify({ model: 'gpt-4.1', temperature: 0.2, max_tokens: 12000, response_format: { type: 'json_object' }, messages: [{ role: 'system', content: SYS }, { role: 'user', content: JSON.stringify(user) }] }) } });
}
return jobs;

const jobs = $('Build jobs').all().map(function (i) { return i.json; });
const res = $input.all().map(function (i) { return i.json || {}; });
// Guides that require straight apostrophes: fr, it, nl, tr.
const STRAIGHT = { fr: 1, it: 1, nl: 1, tr: 1 };
function bag(s, rx) { const m = {}; for (const x of (String(s).match(rx) || [])) { m[x] = (m[x] || 0) + 1; } return JSON.stringify(Object.keys(m).sort().map(function (k) { return k + ':' + m[k]; })); }
