  if (iso !== 'uk' && CYR.test(t) && !CYR.test(en)) { return 'wrong script (Cyrillic)'; }
  if (iso !== 'el' && GRK.test(t) && !GRK.test(en)) { return 'wrong script (Greek)'; }
